const uint8_t RGB_PIN = 38;   // v1.1: the RGB LED's data line is GPIO38 (v1.0: GPIO48)

void setup() {
  Serial.begin(115200);
}

void loop() {
  rgbLedWrite(RGB_PIN, 0, 64, 0);
  Serial.println("green");
  delay(500);
  rgbLedWrite(RGB_PIN, 0, 0, 0);
  Serial.println("off");
  delay(500);
}

